/**
 * Event Bus
 * In-memory pub/sub message broker for service communication
 */

export type EventCallback = (payload: any) => void;

export class EventBus {
  private subscribers: Map<string, EventCallback[]> = new Map();

  /**
   * Subscribe to an event
   */
  subscribe(event: string, callback: EventCallback): void {
    if (!this.subscribers.has(event)) {
      this.subscribers.set(event, []);
    }
    this.subscribers.get(event)!.push(callback);
  }

  /**
   * Publish an event to all subscribers
   */
  publish(event: string, payload: any): void {
    const callbacks = this.subscribers.get(event) || [];
    callbacks.forEach((callback) => {
      try {
        callback(payload);
      } catch (error) {
        console.error(`Error in event subscriber for ${event}:`, error);
      }
    });
  }
}

export const eventBus = new EventBus();

/**
 * User Service
 * Manages user CRUD operations
 */

import { randomUUID } from "crypto";

export interface User {
  id: string;
  name: string;
  email: string;
}

export interface CreateUserRequest {
  name: string;
  email: string;
}

export interface UpdateUserRequest {
  name?: string;
  email?: string;
}

export class UserService {
  private userStore: Map<string, User> = new Map();

  create(req: CreateUserRequest): User {
    const user: User = {
      id: randomUUID(),
      name: req.name,
      email: req.email,
    };
    this.userStore.set(user.id, user);
    return user;
  }

  getById(id: string): User | null {
    return this.userStore.get(id) || null;
  }

  getAll(): User[] {
    return Array.from(this.userStore.values());
  }

  update(id: string, req: UpdateUserRequest): User | null {
    const user = this.userStore.get(id);
    if (!user) return null;

    if (req.name !== undefined) {
      user.name = req.name;
    }
    if (req.email !== undefined) {
      user.email = req.email;
    }

    this.userStore.set(id, user);
    return user;
  }

  delete(id: string): boolean {
    return this.userStore.delete(id);
  }
}

export const userService = new UserService();

/**
 * Project Service
 * Manages projects and membership
 */

import { randomUUID } from "crypto";

export interface Project {
  id: string;
  name: string;
  description: string;
  memberIds: string[];
}

export interface CreateProjectRequest {
  name: string;
  description: string;
}

export interface UpdateProjectRequest {
  name?: string;
  description?: string;
}

export interface AddMemberRequest {
  userId: string;
}

export interface RemoveMemberRequest {
  userId: string;
}

export class ProjectService {
  private projectStore: Map<string, Project> = new Map();

  create(req: CreateProjectRequest): Project {
    const project: Project = {
      id: randomUUID(),
      name: req.name,
      description: req.description,
      memberIds: [],
    };
    this.projectStore.set(project.id, project);
    return project;
  }

  getById(id: string): Project | null {
    return this.projectStore.get(id) || null;
  }

  getAll(): Project[] {
    return Array.from(this.projectStore.values());
  }

  update(id: string, req: UpdateProjectRequest): Project | null {
    const project = this.projectStore.get(id);
    if (!project) return null;

    if (req.name !== undefined) {
      project.name = req.name;
    }
    if (req.description !== undefined) {
      project.description = req.description;
    }

    this.projectStore.set(id, project);
    return project;
  }

  delete(id: string): boolean {
    return this.projectStore.delete(id);
  }

  addMember(projectId: string, userId: string): Project | null {
    const project = this.projectStore.get(projectId);
    if (!project) return null;

    if (!project.memberIds.includes(userId)) {
      project.memberIds.push(userId);
      this.projectStore.set(projectId, project);
    }

    return project;
  }

  removeMember(projectId: string, userId: string): Project | null {
    const project = this.projectStore.get(projectId);
    if (!project) return null;

    project.memberIds = project.memberIds.filter((id) => id !== userId);
    this.projectStore.set(projectId, project);

    return project;
  }
}

export const projectService = new ProjectService();

/**
 * Task Service
 * Manages tasks with status transitions
 */

import { randomUUID } from "crypto";
import { eventBus } from "../event-bus";

export type TaskStatus = "todo" | "in-progress" | "done";

export interface Task {
  id: string;
  title: string;
  description: string;
  status: TaskStatus;
  assigneeId: string | null;
  projectId: string;
}

export interface CreateTaskRequest {
  title: string;
  description: string;
  projectId: string;
}

export interface UpdateTaskRequest {
  title?: string;
  description?: string;
}

export interface AssignRequest {
  assigneeId: string;
}

export interface ChangeStatusRequest {
  status: TaskStatus;
}

export class TaskService {
  private taskStore: Map<string, Task> = new Map();

  create(req: CreateTaskRequest): Task {
    const task: Task = {
      id: randomUUID(),
      title: req.title,
      description: req.description,
      status: "todo",
      assigneeId: null,
      projectId: req.projectId,
    };
    this.taskStore.set(task.id, task);
    return task;
  }

  getById(id: string): Task | null {
    return this.taskStore.get(id) || null;
  }

  getByProject(projectId: string): Task[] {
    return Array.from(this.taskStore.values()).filter(
      (task) => task.projectId === projectId
    );
  }

  update(id: string, req: UpdateTaskRequest): Task | null {
    const task = this.taskStore.get(id);
    if (!task) return null;

    if (req.title !== undefined) {
      task.title = req.title;
    }
    if (req.description !== undefined) {
      task.description = req.description;
    }

    this.taskStore.set(id, task);
    return task;
  }

  delete(id: string): boolean {
    return this.taskStore.delete(id);
  }

  assign(id: string, req: AssignRequest): Task | null {
    const task = this.taskStore.get(id);
    if (!task) return null;

    const oldAssigneeId = task.assigneeId;
    task.assigneeId = req.assigneeId;
    this.taskStore.set(id, task);

    // Publish event
    eventBus.publish("task.assigned", {
      taskId: task.id,
      taskTitle: task.title,
      assigneeId: task.assigneeId,
      oldAssigneeId,
    });

    return task;
  }

  changeStatus(id: string, req: ChangeStatusRequest): Task | null {
    const task = this.taskStore.get(id);
    if (!task) return null;

    // Enforce forward-only transitions: todo -> in-progress -> done
    const validTransitions: Record<TaskStatus, TaskStatus[]> = {
      todo: ["in-progress"],
      "in-progress": ["done"],
      done: [],
    };

    if (!validTransitions[task.status].includes(req.status)) {
      throw new Error(
        `Invalid status transition from ${task.status} to ${req.status}`
      );
    }

    const oldStatus = task.status;
    task.status = req.status;
    this.taskStore.set(id, task);

    // Publish event
    eventBus.publish("task.statusChanged", {
      taskId: task.id,
      taskTitle: task.title,
      assigneeId: task.assigneeId,
      oldStatus,
      newStatus: task.status,
    });

    return task;
  }
}

export const taskService = new TaskService();

/**
 * Comment Service
 * Manages comments on tasks
 */

import { randomUUID } from "crypto";
import { eventBus } from "../event-bus";
import { taskService } from "./task-service";
import { userService } from "./user-service";

export interface Comment {
  id: string;
  taskId: string;
  authorId: string;
  body: string;
  createdAt: string;
}

export interface CreateCommentRequest {
  taskId: string;
  authorId: string;
  body: string;
}

export class CommentService {
  private commentStore: Map<string, Comment> = new Map();

  create(req: CreateCommentRequest): Comment | null {
    // Validate that task exists
    const task = taskService.getById(req.taskId);
    if (!task) return null;

    // Validate that author exists
    const author = userService.getById(req.authorId);
    if (!author) return null;

    const comment: Comment = {
      id: randomUUID(),
      taskId: req.taskId,
      authorId: req.authorId,
      body: req.body,
      createdAt: new Date().toISOString(),
    };

    this.commentStore.set(comment.id, comment);

    // Publish event
    eventBus.publish("comment.added", {
      commentId: comment.id,
      taskId: comment.taskId,
      taskTitle: task.title,
      authorId: comment.authorId,
      authorName: author.name,
    });

    return comment;
  }

  getById(id: string): Comment | null {
    return this.commentStore.get(id) || null;
  }

  getByTask(taskId: string): Comment[] {
    return Array.from(this.commentStore.values()).filter(
      (comment) => comment.taskId === taskId
    );
  }

  delete(id: string): boolean {
    return this.commentStore.delete(id);
  }
}

export const commentService = new CommentService();

/**
 * Notification Service
 * Creates notifications from events
 */

import { randomUUID } from "crypto";
import { eventBus } from "../event-bus";

export interface Notification {
  id: string;
  userId: string;
  message: string;
  read: boolean;
  createdAt: string;
}

export class NotificationService {
  private notificationStore: Map<string, Notification> = new Map();

  constructor() {
    this.initializeSubscriptions();
  }

  private initializeSubscriptions(): void {
    // Subscribe to task.assigned events
    eventBus.subscribe("task.assigned", (payload: any) => {
      if (payload.assigneeId) {
        const message = `Task "${payload.taskTitle}" has been assigned to you`;
        this.createNotification(payload.assigneeId, message);
      }
    });

    // Subscribe to task.statusChanged events
    eventBus.subscribe("task.statusChanged", (payload: any) => {
      if (payload.assigneeId) {
        const message = `Task "${payload.taskTitle}" status changed to ${payload.newStatus}`;
        this.createNotification(payload.assigneeId, message);
      }
    });

    // Subscribe to comment.added events
    eventBus.subscribe("comment.added", (payload: any) => {
      // In a real system, we'd fetch the task to get the assignee
      // For now, we'll rely on the router to coordinate this
      // The notification for task assignee will be created by the router
    });
  }

  private createNotification(
    userId: string,
    message: string
  ): Notification {
    const notification: Notification = {
      id: randomUUID(),
      userId,
      message,
      read: false,
      createdAt: new Date().toISOString(),
    };
    this.notificationStore.set(notification.id, notification);
    return notification;
  }

  getByUser(userId: string): Notification[] {
    return Array.from(this.notificationStore.values())
      .filter((notif) => notif.userId === userId)
      .sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
  }

  markAsRead(id: string): Notification | null {
    const notification = this.notificationStore.get(id);
    if (!notification) return null;

    notification.read = true;
    this.notificationStore.set(id, notification);
    return notification;
  }

  // Internal method for publishing notifications on comment events
  notifyTaskAssigneeOnComment(taskAssigneeId: string | null, taskTitle: string, authorName: string): void {
    if (taskAssigneeId) {
      const message = `${authorName} commented on task "${taskTitle}"`;
      this.createNotification(taskAssigneeId, message);
    }
  }
}

export const notificationService = new NotificationService();

/**
 * API Router
 * HTTP entry point that delegates to services
 */

import { IncomingMessage, ServerResponse } from "http";
import { URL } from "url";
import { userService } from "./services/user-service";
import { projectService } from "./services/project-service";
import { taskService } from "./services/task-service";
import { commentService } from "./services/comment-service";
import { notificationService } from "./services/notification-service";

interface ParsedBody {
  [key: string]: any;
}

async function parseRequestBody(req: IncomingMessage): Promise<ParsedBody> {
  return new Promise((resolve, reject) => {
    let body = "";
    req.on("data", (chunk) => {
      body += chunk.toString();
    });
    req.on("end", () => {
      try {
        resolve(body ? JSON.parse(body) : {});
      } catch (e) {
        reject(new Error("Invalid JSON"));
      }
    });
    req.on("error", reject);
  });
}

function sendJSON(res: ServerResponse, statusCode: number, data: any): void {
  res.writeHead(statusCode, { "Content-Type": "application/json" });
  res.end(JSON.stringify(data, null, 2));
}

function sendError(res: ServerResponse, statusCode: number, message: string): void {
  sendJSON(res, statusCode, { error: message });
}

export async function handleRequest(
  req: IncomingMessage,
  res: ServerResponse
): Promise<void> {
  const url = new URL(req.url || "", `http://${req.headers.host}`);
  const pathname = url.pathname;
  const searchParams = url.searchParams;
  const method = req.method || "GET";

  try {
    // User routes
    if (pathname === "/users" && method === "GET") {
      const users = userService.getAll();
      sendJSON(res, 200, { users });
      return;
    }

    if (pathname === "/users" && method === "POST") {
      const body = await parseRequestBody(req);
      const user = userService.create(body);
      sendJSON(res, 201, { user });
      return;
    }

    const userMatch = pathname.match(/^\/users\/([a-f0-9\-]+)$/);
    if (userMatch && method === "GET") {
      const user = userService.getById(userMatch[1]);
      if (!user) {
        sendError(res, 404, "User not found");
        return;
      }
      sendJSON(res, 200, { user });
      return;
    }

    if (userMatch && method === "PUT") {
      const body = await parseRequestBody(req);
      const user = userService.update(userMatch[1], body);
      if (!user) {
        sendError(res, 404, "User not found");
        return;
      }
      sendJSON(res, 200, { user });
      return;
    }

    if (userMatch && method === "DELETE") {
      const success = userService.delete(userMatch[1]);
      if (!success) {
        sendError(res, 404, "User not found");
        return;
      }
      sendJSON(res, 200, { success: true });
      return;
    }

    // Project routes
    if (pathname === "/projects" && method === "GET") {
      const projects = projectService.getAll();
      sendJSON(res, 200, { projects });
      return;
    }

    if (pathname === "/projects" && method === "POST") {
      const body = await parseRequestBody(req);
      const project = projectService.create(body);
      sendJSON(res, 201, { project });
      return;
    }

    const projectMatch = pathname.match(/^\/projects\/([a-f0-9\-]+)$/);
    if (projectMatch && method === "GET") {
      const project = projectService.getById(projectMatch[1]);
      if (!project) {
        sendError(res, 404, "Project not found");
        return;
      }
      sendJSON(res, 200, { project });
      return;
    }

    if (projectMatch && method === "PUT") {
      const body = await parseRequestBody(req);
      const project = projectService.update(projectMatch[1], body);
      if (!project) {
        sendError(res, 404, "Project not found");
        return;
      }
      sendJSON(res, 200, { project });
      return;
    }

    if (projectMatch && method === "DELETE") {
      const success = projectService.delete(projectMatch[1]);
      if (!success) {
        sendError(res, 404, "Project not found");
        return;
      }
      sendJSON(res, 200, { success: true });
      return;
    }

    // Project member routes
    const projectMemberMatch = pathname.match(
      /^\/projects\/([a-f0-9\-]+)\/members$/
    );
    if (projectMemberMatch && method === "POST") {
      const body = await parseRequestBody(req);
      const project = projectService.addMember(projectMemberMatch[1], body.userId);
      if (!project) {
        sendError(res, 404, "Project not found");
        return;
      }
      sendJSON(res, 200, { project });
      return;
    }

    if (projectMemberMatch && method === "DELETE") {
      const body = await parseRequestBody(req);
      const project = projectService.removeMember(projectMemberMatch[1], body.userId);
      if (!project) {
        sendError(res, 404, "Project not found");
        return;
      }
      sendJSON(res, 200, { project });
      return;
    }

    // Task routes
    if (pathname === "/tasks" && method === "GET") {
      const projectId = searchParams.get("projectId");
      let tasks;
      if (projectId) {
        tasks = taskService.getByProject(projectId);
      } else {
        tasks = [];
      }
      sendJSON(res, 200, { tasks });
      return;
    }

    if (pathname === "/tasks" && method === "POST") {
      const body = await parseRequestBody(req);
      const task = taskService.create(body);
      sendJSON(res, 201, { task });
      return;
    }

    const taskMatch = pathname.match(/^\/tasks\/([a-f0-9\-]+)$/);
    if (taskMatch && method === "GET") {
      const task = taskService.getById(taskMatch[1]);
      if (!task) {
        sendError(res, 404, "Task not found");
        return;
      }
      sendJSON(res, 200, { task });
      return;
    }

    if (taskMatch && method === "PUT") {
      const body = await parseRequestBody(req);
      const task = taskService.update(taskMatch[1], body);
      if (!task) {
        sendError(res, 404, "Task not found");
        return;
      }
      sendJSON(res, 200, { task });
      return;
    }

    if (taskMatch && method === "DELETE") {
      const success = taskService.delete(taskMatch[1]);
      if (!success) {
        sendError(res, 404, "Task not found");
        return;
      }
      sendJSON(res, 200, { success: true });
      return;
    }

    // Task status routes
    const taskStatusMatch = pathname.match(/^\/tasks\/([a-f0-9\-]+)\/status$/);
    if (taskStatusMatch && method === "PUT") {
      const body = await parseRequestBody(req);
      const task = taskService.changeStatus(taskStatusMatch[1], body);
      if (!task) {
        sendError(res, 404, "Task not found");
        return;
      }
      sendJSON(res, 200, { task });
      return;
    }

    // Task assign routes
    const taskAssignMatch = pathname.match(/^\/tasks\/([a-f0-9\-]+)\/assign$/);
    if (taskAssignMatch && method === "PUT") {
      const body = await parseRequestBody(req);
      const task = taskService.assign(taskAssignMatch[1], body);
      if (!task) {
        sendError(res, 404, "Task not found");
        return;
      }
      sendJSON(res, 200, { task });
      return;
    }

    // Comment routes
    if (pathname === "/comments" && method === "GET") {
      const taskId = searchParams.get("taskId");
      let comments;
      if (taskId) {
        comments = commentService.getByTask(taskId);
      } else {
        comments = [];
      }
      sendJSON(res, 200, { comments });
      return;
    }

    if (pathname === "/comments" && method === "POST") {
      const body = await parseRequestBody(req);
      const comment = commentService.create(body);
      if (!comment) {
        sendError(res, 400, "Invalid task or author");
        return;
      }

      // Notify task assignee on comment
      const task = taskService.getById(body.taskId);
      if (task && task.assigneeId) {
        const author = userService.getById(body.authorId);
        if (author) {
          notificationService.notifyTaskAssigneeOnComment(
            task.assigneeId,
            task.title,
            author.name
          );
        }
      }

      sendJSON(res, 201, { comment });
      return;
    }

    const commentMatch = pathname.match(/^\/comments\/([a-f0-9\-]+)$/);
    if (commentMatch && method === "GET") {
      const comment = commentService.getById(commentMatch[1]);
      if (!comment) {
        sendError(res, 404, "Comment not found");
        return;
      }
      sendJSON(res, 200, { comment });
      return;
    }

    if (commentMatch && method === "DELETE") {
      const success = commentService.delete(commentMatch[1]);
      if (!success) {
        sendError(res, 404, "Comment not found");
        return;
      }
      sendJSON(res, 200, { success: true });
      return;
    }

    // Notification routes
    if (pathname === "/notifications" && method === "GET") {
      const userId = searchParams.get("userId");
      let notifications;
      if (userId) {
        notifications = notificationService.getByUser(userId);
      } else {
        notifications = [];
      }
      sendJSON(res, 200, { notifications });
      return;
    }

    const notificationMatch = pathname.match(
      /^\/notifications\/([a-f0-9\-]+)\/read$/
    );
    if (notificationMatch && method === "PUT") {
      const notification = notificationService.markAsRead(notificationMatch[1]);
      if (!notification) {
        sendError(res, 404, "Notification not found");
        return;
      }
      sendJSON(res, 200, { notification });
      return;
    }

    // 404
    sendError(res, 404, "Not found");
  } catch (error) {
    const message = error instanceof Error ? error.message : "Internal server error";
    sendError(res, 500, message);
  }
}

/**
 * Main entry point
 * Starts the HTTP server
 */

import { createServer } from "http";
import { handleRequest } from "./router";

const PORT = process.env.PORT ? parseInt(process.env.PORT) : 3000;

const server = createServer(async (req, res) => {
  // Enable CORS headers
  res.setHeader("Access-Control-Allow-Origin", "*");
  res.setHeader("Access-Control-Allow-Methods", "GET, POST, PUT, DELETE, OPTIONS");
  res.setHeader("Access-Control-Allow-Headers", "Content-Type");

  if (req.method === "OPTIONS") {
    res.writeHead(200);
    res.end();
    return;
  }

  await handleRequest(req, res);
});

server.listen(PORT, () => {
  console.log(`Task Management API listening on http://localhost:${PORT}`);
});

// Graceful shutdown
process.on("SIGINT", () => {
  console.log("\nShutting down gracefully...");
  server.close(() => {
    console.log("Server closed");
    process.exit(0);
  });
});

/**
 * Demo Script
 * Demonstrates the full workflow of the Task Management API
 */

import { createServer } from "http";
import { handleRequest } from "./router";

const PORT = 3000;

interface ApiResponse {
  status: number;
  data: any;
}

async function apiCall(
  method: string,
  path: string,
  body?: any
): Promise<ApiResponse> {
  return new Promise((resolve, reject) => {
    const url = new URL(path, `http://localhost:${PORT}`);
    const options = {
      hostname: url.hostname,
      port: url.port || PORT,
      path: url.pathname + url.search,
      method,
      headers: {
        "Content-Type": "application/json",
      },
    };

    const req = require("http").request(options, (res: any) => {
      let data = "";
      res.on("data", (chunk: any) => {
        data += chunk;
      });
      res.on("end", () => {
        try {
          resolve({
            status: res.statusCode,
            data: JSON.parse(data),
          });
        } catch {
          resolve({
            status: res.statusCode,
            data: { error: data },
          });
        }
      });
    });

    req.on("error", reject);

    if (body) {
      req.write(JSON.stringify(body));
    }
    req.end();
  });
}

